begin;
create table if not exists public.content_generation_jobs (id uuid primary key default gen_random_uuid(),topic text not null,audience text not null,formats text[] not null,tone text not null,language text not null default 'English',carousel_slide_count integer not null default 10 check (carousel_slide_count between 5 and 20),knowledge_entry_ids text[] not null default '{}',provider text not null,model text not null,status text not null default 'queued' check(status in('queued','running','completed','failed','cancelled')),requested_by uuid references auth.users(id) on delete set null,error_message text,started_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.content_bundles (id uuid primary key default gen_random_uuid(),job_id uuid references public.content_generation_jobs(id) on delete set null,topic text not null,audience text not null,language text not null default 'English',status text not null default 'medical_review' check(status in('draft','medical_review','approved','rejected','archived')),knowledge_entry_ids text[] not null default '{}',knowledge_snapshot jsonb not null default '[]'::jsonb,model text not null,blog jsonb,facebook jsonb,carousel jsonb,reel jsonb,pinterest jsonb,email jsonb,youtube jsonb,safety_report jsonb not null default '{}'::jsonb,brand_report jsonb not null default '{}'::jsonb,generated_at timestamptz not null default now(),reviewed_by uuid references auth.users(id) on delete set null,reviewed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists content_generation_jobs_status_idx on public.content_generation_jobs(status);create index if not exists content_bundles_status_idx on public.content_bundles(status);alter table public.content_generation_jobs enable row level security;alter table public.content_bundles enable row level security;revoke all on table public.content_generation_jobs from anon,authenticated;revoke all on table public.content_bundles from anon,authenticated;commit;
